content.solutionCode:
const sampleLessons = [
  { title: 'Variables', score: 90, completed: true },
  { title: 'Data Types', score: 80, completed: true },
  { title: 'Loops', score: 100, completed: true },
  { title: 'Projects', score: 0, completed: false }
];

function generateProgressReport(lessons) {
  const completedLessons = lessons.filter(l => l.completed === true);
  const completedCount = completedLessons.length;

  let scoreSum = 0;
  for (let i = 0; i < completedLessons.length; i++) {
    scoreSum += completedLessons[i].score;
  }
  const averageScore = completedCount > 0 ? scoreSum / completedCount : 0;

  let tier = 'Bronze';
  if (averageScore >= 90) {
    tier = 'Gold';
  } else if (averageScore >= 75) {
    tier = 'Silver';
  }

  return {
    total: lessons.length,
    completed: completedCount,
    average: averageScore,
    tier: tier
  };
}

const report = generateProgressReport(sampleLessons);
